// Build step for the docx viewer (FR-42), mirroring src/lib/cm/build-bundle.mjs:
// bundle docx-entry.mjs (and mammoth with it) into one IIFE and emit it as a TS string
// constant that html.ts inlines into the WebView page.
//   node src/lib/docx/build-bundle.mjs
//
// platform: "browser" matters — mammoth's package.json maps unzip and file
// reading to browser implementations there; the node ones would pull in fs.
import { build } from "esbuild";
import { writeFileSync } from "node:fs";

const result = await build({
  entryPoints: ["src/lib/docx/docx-entry.mjs"],
  bundle: true,
  format: "iife",
  platform: "browser",
  minify: true,
  target: "safari15",
  write: false,
});
const code = result.outputFiles[0].text;
const out = `// AUTO-GENERATED by src/lib/docx/build-bundle.mjs — do not edit by hand.\n/* eslint-disable */\nexport const DOCX_BUNDLE = ${JSON.stringify(code)};\n`;
writeFileSync("src/lib/docx/bundle.ts", out);
console.log(`wrote src/lib/docx/bundle.ts (${(code.length / 1024) | 0} KB minified)`);
